<?php use function KB\{e,url}; use KB\Security; ?><section class="page-heading"><div><span class="eyebrow">EVERY IMPORTANT MOMENT</span><h1>Messages that keep moving.</h1><p>Notifications are stored safely before delivery. A slow email provider never holds up a quiz.</p></div><form method="post"><?= Security::csrfField() ?><button name="action" value="test" class="button">Queue test message +</button></form></section><div class="notice info"><div><strong>Background delivery</strong><p>Run <code>php bin/worker.php</code> every minute. In production, delivery is command-line only. Message bodies and reset links are not shown here.</p></div><?php if(KB\config('local_preview',false)): ?><form method="post"><?= Security::csrfField() ?><button name="action" value="process" class="button secondary small">Run local worker</button></form><?php endif; ?></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Message</th><th>Status</th><th>Delivery attempts</th><th>Created (UTC)</th><th>Action</th></tr></thead><tbody><?php foreach($mails as $mail): ?><tr><td><strong><?= e($mail['subject']) ?></strong><small><?= e($mail['recipient']) ?></small><?php if($mail['last_error']): ?><small class="danger-text"><?= e($mail['last_error']) ?></small><?php endif; ?></td><td><span class="badge <?= $mail['status']==='sent'?'green':($mail['status']==='failed'?'red':'neutral') ?>"><?= e(ucfirst($mail['status'])) ?></span></td><td><?= (int)$mail['attempts'] ?><small><?= (int)$mail['deliveries'] ?> successful</small></td><td><?= e($mail['created_at']) ?></td><td><?php if($mail['status']==='failed'): ?><form method="post"><?= Security::csrfField() ?><input type="hidden" name="id" value="<?= (int)$mail['id'] ?>"><button name="action" value="retry" class="inline-button">Retry delivery</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php if(!$mails): ?><p class="empty">No notifications yet.</p><?php endif; ?></div><?php require __DIR__.'/../pagination.php'; ?></section>
